struct FaunaTypeInfo {
	const char *template_name; // gaia/<template_name>.xml
	const char *name;          // Identity/GenericName
	const char *model_id;      // assets/models/units/<model_id>.glb
	float max_hp;
	float speed;               // walk speed, RTS0 units/s
	float run_mult;            // UnitMotion/RunMultiplier (fleeing and chasing)
	int food_amount;           // ResourceSupply/Max (0: not huntable)
	uint8_t max_gatherers;
	uint8_t stance;            // FaunaStance
	uint8_t flags;             // FaunaFlags
	float vision;              // Vision/Range: aggressive animals attack, skittish flee, inside it
	float flee_distance;       // UnitAI/FleeDistance
	float roam_distance;       // UnitAI/RoamDistance
	float roam_time_min, roam_time_max, feed_time_min, feed_time_max; // seconds
	float hack_damage, pierce_damage, crush_damage; // Attack/Melee/Damage
	float attack_range;        // Attack/Melee/MaxRange
	float attack_cooldown;     // Attack/Melee/RepeatTime, seconds
	float attack_prepare;      // Attack/Melee/PrepareTime, seconds: the first hit waits this long
	float hack_armor, pierce_armor, crush_armor; // Resistance levels (0.9^level)
	float loot_xp;
	float footprint;          // Footprint radius in 0 A.D. metres (a square as the circle of equal area)
	float acceleration;       // UnitMotion/Acceleration in RTS0 units/s^2 (0.28's m/s^2 x the speed scale)
	uint16_t weight;          // UnitMotion/Weight: how hard it pushes and how hard it is to push
	bool is_domestic() const { return flags & FAUNA_F_DOMESTIC; }
	bool is_naval() const { return flags & FAUNA_F_NAVAL; }
	bool is_large() const { return flags & FAUNA_F_LARGE; }
	bool blocks_movement() const { return !(flags & FAUNA_F_NO_BLOCK_MOVEMENT); }
	float attack_damage() const { return hack_damage + pierce_damage + crush_damage; }
	// UnitAI.IsDangerousAnimal: an animal whose stance targets visible enemies and that can attack.
	bool is_dangerous() const {
		return attack_damage() > 0.0f && (stance == FAUNA_STANCE_DEFENSIVE || stance == FAUNA_STANCE_AGGRESSIVE || stance == FAUNA_STANCE_VIOLENT);
	}
};

