// Template stem ("fauna_bear_brown", or "bear_brown") to FaunaType; FAUNA_COUNT if unknown.
inline uint8_t fauna_type_by_name(const char *s) {
	if (!s) return FAUNA_COUNT;
	auto eq = [](const char *a, const char *b) { while (*a && *a == *b) { ++a; ++b; } return *a == *b; };
	const char *bare = s;
	if (s[0] == 'f' && s[1] == 'a' && s[2] == 'u' && s[3] == 'n' && s[4] == 'a' && s[5] == '_') bare = s + 6;
	for (uint8_t i = 0; i < FAUNA_COUNT; ++i)
		if (eq(fauna_type_info(i).template_name + 6, bare)) return i;
	return FAUNA_COUNT;
}

